package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.domain.jobs.ApiRuntimeTelemetry;import com.lianxibu.site.repository.jobs.ProcessApiRuntimeTelemetry;import com.lianxibu.site.service.jobs.OperationalRuleEngine.*;import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.Test;
class ApiMonitoringCycleTest {
 static final Instant START=ApiWindowWatermarkTest.START;static final Key KEY=ApiWindowWatermarkTest.KEY;
 static final class Fixture{final OperationalPersistenceFixture db=new OperationalPersistenceFixture();final AtomicLong nanos=new AtomicLong();final ProcessApiRuntimeTelemetry probe;final ProcessApiRuntimeTelemetry.Capture capture;Fixture(){db.clock.now=START.minusSeconds(300);probe=new ProcessApiRuntimeTelemetry(db.clock,nanos::get,START.minusSeconds(1000),ApiWindowWatermarkTest.EPOCH);capture=probe.openCapture();}void advance(long seconds){db.clock.now=db.clock.now.plusSeconds(seconds);nanos.addAndGet(seconds*1000000000L);}void events(){for(int n=0;n<100;n++)probe.completedHttp(n<10?503:200);}ApiMonitoringCycle cycle(ApiRuntimeTelemetry.Api api){var store=db.store();var cycle=new ApiMonitoringCycle(KEY,api,store,db.monitor(store),db.clock);cycle.start();return cycle;}}
 @Test void actualProcessWindowCommitsPermanentAlarmAndRestartSkipsOriginalMinute(){var f=new Fixture();try(var capture=f.capture){f.events();f.advance(300);var calls=new AtomicInteger();ApiRuntimeTelemetry.Api api=()->{calls.incrementAndGet();assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());return f.probe.read();};assertEquals(ApiMonitoringCycle.Outcome.SAMPLED,f.cycle(api).tick());var original=f.db.store().read(KEY);assertEquals(Level.CRITICAL,original.level());assertEquals(1,original.counters().get("api_required"));assertEquals(ApiMonitoringCycle.Outcome.ALREADY_SAMPLED,f.cycle(api).tick());assertEquals(1,calls.get());f.advance(60);capture.close();f.cycle(api).tick();var unknown=f.db.store().read(KEY);assertEquals(Status.TELEMETRY_UNKNOWN,unknown.status());assertEquals(Level.CRITICAL,unknown.level());assertEquals(original.counters().get("api_end_micros"),unknown.counters().get("api_end_micros"));}}
 @Test void partialStartupAndNativeFailureAreUnknownAndAcquisitionInsideTransactionIsRefused(){var f=new Fixture();try(var capture=f.capture){var cycle=f.cycle(f.probe);cycle.tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.db.store().read(KEY).status());f.advance(60);f.cycle(()->{throw new IllegalStateException("fictional telemetry unavailable");}).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.db.store().read(KEY).status());assertThrows(IllegalStateException.class,()->new org.springframework.transaction.support.TransactionTemplate(f.db.tx).execute(s->cycle.tick()));}}
 @Test void crossMinuteAndFutureNativeReadNeverCommitHealthyAndClockRollbackRejects(){var f=new Fixture();try(var capture=f.capture){f.events();f.advance(300);f.cycle(()->{f.advance(61);return f.probe.read();}).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.db.store().read(KEY).status());f.advance(60);var future=ApiWindowWatermarkTest.value(2,100,0,0).facts();var bad=new ApiRuntimeTelemetry.Evidence(future.processEpoch(),future.startedAt(),future.windowStart(),future.windowEnd(),100,0,0,0,f.db.clock.now.plusSeconds(1));f.cycle(()->bad).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.db.store().read(KEY).status());f.db.clock.now=START;assertThrows(IllegalStateException.class,()->f.cycle(f.probe).tick());}}
 @Test void singleFlightAndStopBeforeWriterCannotEmitLateSample()throws Exception{var f=new Fixture();try(var capture=f.capture){f.events();f.advance(300);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var cycle=f.cycle(()->{entered.countDown();try{assertTrue(release.await(2,TimeUnit.SECONDS));}catch(InterruptedException failure){Thread.currentThread().interrupt();return null;}return f.probe.read();});var pool=Executors.newSingleThreadExecutor();try{var call=pool.submit(cycle::tick);assertTrue(entered.await(1,TimeUnit.SECONDS));assertEquals(ApiMonitoringCycle.Outcome.BUSY,cycle.tick());cycle.stop();release.countDown();assertEquals(ApiMonitoringCycle.Outcome.STOPPED,call.get(2,TimeUnit.SECONDS));assertNull(f.db.store().read(KEY));assertEquals(ApiMonitoringCycle.Outcome.STOPPED,cycle.tick());}finally{release.countDown();pool.shutdownNow();}}}
}
